"""Gestor de gastos personales.

Este es el codigo que "ya existe". Funciona, se usa a diario y no tiene
ni una sola prueba. Guardalo tal cual, sin cambiar nada, en gastos.py
dentro de la carpeta gastos-cli.
"""

import json
import os
from datetime import date


def ruta_fichero():
    """Dónde se guardan los gastos.

    Sale de una variable de entorno (un ajuste que vive fuera del
    código, en el sistema). Así las pruebas pueden apuntar a un fichero
    de usar y tirar sin tocar tus datos de verdad.
    """
    return os.environ.get("GASTOS_FICHERO", "gastos.json")


def cargar():
    """Lee la lista de gastos del disco. Si no hay fichero, lista vacía."""
    ruta = ruta_fichero()
    if not os.path.exists(ruta):
        return []
    with open(ruta, "r", encoding="utf-8") as f:
        return json.load(f)


def guardar(gastos):
    """Escribe la lista entera en el disco, en formato JSON."""
    with open(ruta_fichero(), "w", encoding="utf-8") as f:
        json.dump(gastos, f, ensure_ascii=False, indent=2)


def anadir(concepto, importe, fecha=None):
    """Apunta un gasto nuevo y devuelve el gasto creado."""
    if importe <= 0:
        raise ValueError("El importe tiene que ser mayor que cero")
    gasto = {
        "concepto": concepto.strip(),
        "importe": round(float(importe), 2),
        "fecha": fecha or date.today().isoformat(),
    }
    gastos = cargar()
    gastos.append(gasto)
    guardar(gastos)
    return gasto


def entre_fechas(gastos, desde, hasta):
    """Gastos con fecha entre desde y hasta, los dos días incluidos.

    Las fechas son texto tipo "2026-03-15". Escritas así, comparar
    textos es lo mismo que comparar fechas.
    """
    return [g for g in gastos if desde <= g["fecha"] < hasta]


def total(gastos):
    """Suma de los importes de una lista de gastos."""
    return round(sum(g["importe"] for g in gastos), 2)


def media_diaria(gastos):
    """Gasto medio por cada día en el que hubo al menos un gasto."""
    dias = {g["fecha"] for g in gastos}
    return round(total(gastos) / len(dias), 2)


def buscar(gastos, texto):
    """Gastos cuyo concepto contiene el texto buscado."""
    return [g for g in gastos if texto in g["concepto"]]


def con_iva(importe, tipo=21):
    """Añade el IVA a un importe. Por defecto, el tipo general del 21%."""
    return round(importe * (1 + tipo / 100), 2)

"""gastos.py con los tres fallos corregidos.

Sustituye el contenido entero de gastos.py por esto. Los cambios son
tres y están marcados con el comentario ARREGLO.
"""

import json
import os
from datetime import date


def ruta_fichero():
    """Dónde se guardan los gastos. Sale de una variable de entorno."""
    return os.environ.get("GASTOS_FICHERO", "gastos.json")


def cargar():
    """Lee la lista de gastos del disco. Si no hay fichero, lista vacía."""
    ruta = ruta_fichero()
    if not os.path.exists(ruta):
        return []
    with open(ruta, "r", encoding="utf-8") as f:
        return json.load(f)


def guardar(gastos):
    """Escribe la lista entera en el disco, en formato JSON."""
    with open(ruta_fichero(), "w", encoding="utf-8") as f:
        json.dump(gastos, f, ensure_ascii=False, indent=2)


def anadir(concepto, importe, fecha=None):
    """Apunta un gasto nuevo y devuelve el gasto creado."""
    if importe <= 0:
        raise ValueError("El importe tiene que ser mayor que cero")
    gasto = {
        "concepto": concepto.strip(),
        "importe": round(float(importe), 2),
        "fecha": fecha or date.today().isoformat(),
    }
    gastos = cargar()
    gastos.append(gasto)
    guardar(gastos)
    return gasto


def entre_fechas(gastos, desde, hasta):
    """Gastos con fecha entre desde y hasta, los dos días incluidos."""
    # ARREGLO 1: antes ponía  < hasta  y se comía el último día del mes.
    # Con el 31 de marzo fuera, el total de marzo salía 18,90 EUR corto.
    return [g for g in gastos if desde <= g["fecha"] <= hasta]


def total(gastos):
    """Suma de los importes de una lista de gastos."""
    return round(sum(g["importe"] for g in gastos), 2)


def media_diaria(gastos):
    """Gasto medio por cada día en el que hubo al menos un gasto."""
    dias = {g["fecha"] for g in gastos}
    # ARREGLO 2: sin esto, dividir entre 0 días reventaba el programa
    # el primer día de uso, cuando todavía no hay ningún gasto.
    if not dias:
        return 0.0
    return round(total(gastos) / len(dias), 2)


def buscar(gastos, texto):
    """Gastos cuyo concepto contiene el texto buscado."""
    # ARREGLO 3: antes distinguía mayúsculas, así que buscar "mercadona"
    # no encontraba "Mercadona". Ahora se comparan los dos en minúsculas.
    texto = texto.lower()
    return [g for g in gastos if texto in g["concepto"].lower()]


def con_iva(importe, tipo=21):
    """Añade el IVA a un importe. Por defecto, el tipo general del 21%."""
    return round(importe * (1 + tipo / 100), 2)


